import{_ as i,o as l,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Day CERN 2019- Utilising Ceph for large scale to support the LHC experiments - Tom Byrne","description":"","frontmatter":{"title":"Ceph Day CERN 2019- Utilising Ceph for large scale to support the LHC experiments - Tom Byrne","date":"2020-08-25T00:00:00.000Z","updated":"2020-08-26T00:00:00.000Z","tags":["Ceph","LHC实验","分布式存储","高吞吐量","数据处理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Day_CERN_2019_-_Utilising_Ceph_for_large_scale_to_support_the_LHC_experiments_-_Tom_Byrne.md","filePath":"posts/2020/Ceph_Day_CERN_2019_-_Utilising_Ceph_for_large_scale_to_support_the_LHC_experiments_-_Tom_Byrne.md","lastUpdated":1780459816000}'),r={name:"posts/2020/Ceph_Day_CERN_2019_-_Utilising_Ceph_for_large_scale_to_support_the_LHC_experiments_-_Tom_Byrne.md"};function o(_,e,s,p,n,h){return l(),t("div",null,[...e[0]||(e[0]=[a('<p>会议纪要：</p><h3 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h3><p>利用Ceph支持大型高吞吐量存储以支持LHC实验</p><h3 id="会议参与者" tabindex="-1">会议参与者 <a class="header-anchor" href="#会议参与者" aria-label="Permalink to &quot;会议参与者&quot;">​</a></h3><p>Tom Byrne等</p><h3 id="会议内容总结" tabindex="-1">会议内容总结 <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结&quot;">​</a></h3><ol><li><p><strong>Ceph集群介绍</strong>：</p><ul><li>Tom Byrne介绍了名为ECHO的Ceph集群，该集群位于英国的Rutherford Appleton实验室，服务于LHC实验。</li><li>ECHO集群拥有180个存储节点，5000个OSDs，并准备扩展。</li><li>数据池采用EC 8+3配置，使用librados striker，对象大小为64MB。</li><li>集群运行在Luminous版本，并开始测试Mimic版本。</li></ul></li><li><p><strong>LHC实验背景</strong>：</p><ul><li>LHC实验在全球LHC计算网格中有大量计算和存储需求，Tier 1站点提供约40%的计算和存储资源。</li><li>ECHO集群为LHC实验提供所有磁盘存储，支持大规模数据处理。</li></ul></li><li><p><strong>数据处理流程</strong>：</p><ul><li>实验数据从Tier 0转移到Tier 1存储，如ECHO集群，并模拟大量碰撞数据。</li><li>数据需要重建，从探测器读数到粒子的动量和轨迹，通常在Tier 1进行。</li></ul></li><li><p><strong>数据访问架构</strong>：</p><ul><li>主要使用GridFTP进行广域网传输，XRootD用于作业输入输出文件传输。</li><li>集群通过7个网关机器提供服务，XRootD服务器基础设施被容器化。</li></ul></li><li><p><strong>监控和性能问题</strong>：</p><ul><li>集群运行稳定，但偶尔会出现性能问题，影响外部传输。</li><li>缺乏监控使得定位和解决这些问题变得困难。</li><li>通过脚本收集慢请求的详细信息，并将其导入Elasticsearch进行分析。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>继续监控和优化ECHO集群的性能，特别是解决已知的性能瓶颈。</li><li>等待Ceph新版本的发布，以解决当前已知的问题。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>加强集群的监控系统，确保能够及时发现和解决性能问题。</li><li>继续测试和部署Ceph的新版本，以利用新功能和修复。</li><li>优化数据处理流程，提高数据传输和处理的效率。</li></ul><h3 id="关键词" tabindex="-1">关键词 <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词&quot;">​</a></h3><ul><li>Ceph</li><li>ECHO集群</li><li>LHC实验</li><li>Tier 1站点</li><li>GridFTP</li><li>XRootD</li><li>Elasticsearch</li><li>OSDs</li><li>librados striker</li></ul>',13)])])}const d=i(r,[["render",o]]);export{u as __pageData,d as default};
